-- Plano de ação por setor: o que cada área faz em cada mês, como, por que e quem.
-- O número sozinho não faz ninguém executar; isto é a parte que executa.

create table if not exists planejamento_acoes (
  id          uuid primary key default gen_random_uuid(),
  ano         integer not null references planejamento_anos(ano) on delete cascade,
  setor       text not null,
  ordem_setor integer not null default 0,
  -- mês de início (1 a 12); acao_continua marca o que roda todo mês a partir daí
  mes         integer not null check (mes between 1 and 12),
  mes_fim     integer check (mes_fim between 1 and 12),
  continua    boolean not null default false,
  titulo      text not null,
  o_que       text not null,
  como        text not null,
  por_que     text not null,
  quem        text not null,
  indicador   text,
  prioridade  text not null default 'media' check (prioridade in ('alta', 'media', 'baixa')),
  status      text not null default 'planejada' check (status in ('planejada', 'fazendo', 'feita', 'cancelada')),
  observacao  text,
  criado_em   timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);

create index if not exists idx_planejamento_acoes on planejamento_acoes (ano, setor, mes);

alter table planejamento_acoes enable row level security;
drop policy if exists planejamento_acoes_master on planejamento_acoes;
create policy planejamento_acoes_master on planejamento_acoes
  for all to authenticated using (is_master()) with check (is_master());
grant select, insert, update, delete on planejamento_acoes to authenticated;

drop trigger if exists trg_planejamento_acoes_touch on planejamento_acoes;
create trigger trg_planejamento_acoes_touch before update on planejamento_acoes
  for each row execute function planejamento_touch();
delete from planejamento_acoes where ano = 2027;
insert into planejamento_acoes (ano, setor, ordem_setor, mes, mes_fim, continua, titulo, o_que, como, por_que, quem, indicador, prioridade) values
  (2027, 'Comercial', 10, 1, null, false, 'Ligar a renovação 45 dias antes', 'Toda empresa com contrato vencendo em 45 dias entra numa fila de renovação com reunião obrigatória agendada pelo sistema.', 'Automação no Nexus lê a data de término do projeto e cria a tarefa para o consultor dono, com o painel de resultado do cliente anexado. Sem reunião marcada em 7 dias, escala para o Fabrício.', 'Em 2026 saíram 55 clientes contra 67 que entraram: 82% do esforço comercial foi repor perda. A renovação não acontecia porque ninguém era cobrado por ela.', 'Fabrício, com execução de Taynon e Natállia', 'contratos renovados / contratos vencendo', 'alta'),
  (2027, 'Comercial', 20, 1, null, false, 'Publicar a tabela de preços e a esteira', 'Tabela única de preços de 2027 e a escada de produtos, da Mesa gratuita ao Conselho, publicada para o time inteiro.', 'Um documento só, com preço de tabela, desconto máximo autorizado por produto e quem pode aprovar exceção. Apresentado em reunião, não enviado por mensagem.', 'A carteira paga em média R$ 1.852 porque cada negociação virou um preço diferente. Sem tabela publicada, o desconto é a saída fácil de todo vendedor.', 'Fabrício', 'ticket médio das vendas novas', 'alta'),
  (2027, 'Comercial', 2, 2, null, false, 'Campanha de reajuste na renovação', 'Nenhuma renovação de 2027 sai pelo valor antigo. Reajuste mínimo de inflação, e correção para a tabela nos contratos muito defasados.', 'Lista dos contratos abaixo de R$ 1.500 ordenada por tempo de casa. O argumento é o resultado entregue, mostrado no painel do cliente, não o custo da UNV.', 'Ticket médio é a alavanca de margem mais barata que existe: não exige vender mais nem contratar ninguém. Subir de R$ 1.852 para R$ 2.400 vale R$ 26 mil por mês na carteira atual.', 'Taynon e Natállia, com o Fabrício nos casos difíceis', 'ticket médio da carteira', 'alta'),
  (2027, 'Comercial', 30, 4, null, false, 'Entra o SDR', 'Contratar o SDR no formato antigo: fixo de R$ 2.000 mais R$ 60 por reunião realizada acima de 70% da meta de 30 por mês.', 'Busca por indicação do próprio time e nos grupos de vendas. Período de 30 dias com meta reduzida. A régua é reunião REALIZADA, não agendada.', 'O closer sozinho sustenta 13 reuniões por mês e o plano pede 29 em dezembro. O SDR tem que entrar antes do volume: chegar depois é contratar para apagar incêndio.', 'Fabrício contrata, Ricardo treina', 'reuniões realizadas por mês', 'alta'),
  (2027, 'Comercial', 40, 1, null, false, 'Programa de indicação de R$ 500', 'R$ 500 por indicação que fecha, pago no primeiro pagamento do cliente, para cliente, parceiro ou qualquer pessoa de fora.', 'Anúncio na base por WhatsApp e no grupo de clientes, com um link de indicação que registra quem indicou. Pagamento junto com a comissão do mês.', 'Com CAC de mídia projetado em R$ 1.200, a indicação custa 42% de um lead pago e converte muito mais. É o canal mais barato do plano e hoje ninguém trabalha ele de propósito.', 'Fabrício anuncia, Yasmim controla o pagamento', 'contratos originados por indicação', 'alta'),
  (2027, 'Comercial', 50, 1, null, true, 'Rotina de gestão comercial', 'Diária: leads do dia, reuniões agendadas, follow-ups vencidos. Semanal: pipeline por consultor, contratos vencendo em 45 dias, clientes em risco. Mensal: comissão, NPS, churn e renovações do mês seguinte.', 'Reunião de 15 minutos em pé toda manhã e uma hora de pipeline na segunda. O painel do Nexus é a pauta; quem não atualizou o CRM não tem o que apresentar.', 'Reunião sem métrica é terapia em grupo. A rotina é o que transforma meta em comportamento diário.', 'Fabrício', 'reuniões realizadas e vendas por semana', 'alta'),
  (2027, 'Marketing e tráfego', 10, 1, null, false, 'Tráfego em R$ 4.000 com CAC medido', 'Começar o ano com R$ 4.000 por mês de mídia e medir CAC por campanha, não no agregado.', 'Pixel e CAPI ligados, conversão de reunião agendada como evento de otimização. Campanha por produto, não uma só genérica. Nada de Advantage+ e nada de público relacionado.', 'Sem CAC por campanha não dá para saber qual desligar. Em 2026 o tráfego virou dívida porque o gasto crescia sem ninguém olhar o retorno por origem.', 'Weslley', 'CAC de mídia por contrato', 'alta'),
  (2027, 'Marketing e tráfego', 20, 4, null, false, 'Subir para R$ 8.000, se o gatilho bater', 'Dobrar o investimento em mídia para R$ 8.000 por mês.', 'Só acontece se, no fechamento de março, o CAC de mídia estiver abaixo de R$ 1.500 E o churn do trimestre em até 2,5 por mês. Se um dos dois falhar, mantém R$ 4.000.', 'Escalar mídia com churn alto é encher um balde furado: paga-se caro para repor cliente que já estava saindo.', 'Weslley propõe, Fabrício autoriza', 'CAC abaixo de R$ 1.500 e churn até 2,5', 'alta'),
  (2027, 'Marketing e tráfego', 30, 7, null, false, 'Subir para R$ 14.000, se o gatilho bater', 'Terceiro degrau de mídia, R$ 14.000 por mês.', 'Condição medida no fechamento de junho: CAC abaixo de R$ 1.800 e churn em até 2,5 por mês.', 'O CAC sobe naturalmente quando se escala mídia; o degrau aceita essa subida, mas com teto.', 'Weslley propõe, Fabrício autoriza', 'CAC abaixo de R$ 1.800', 'media'),
  (2027, 'Marketing e tráfego', 40, 10, null, false, 'Subir para R$ 20.000, se o gatilho bater', 'Último degrau, R$ 20.000 por mês.', 'Condição medida no fechamento de setembro: CAC abaixo de R$ 2.000 e caixa com um mês de reserva construído.', 'O último degrau exige caixa, não só CAC: é o ponto em que um mês ruim de mídia doeria de verdade.', 'Weslley propõe, Fabrício autoriza', 'CAC abaixo de R$ 2.000 e reserva de 1 mês', 'media'),
  (2027, 'Marketing e tráfego', 50, 1, null, true, 'Conteúdo com as quatro dores do ICP', 'Produção semanal de conteúdo em cima das quatro dores que aparecem no diagnóstico: não bate meta, não tem previsibilidade, depende do dono, ticket baixo.', 'Formato lo-fi, câmera estática, fundo real, sem vinheta. Um tema por semana, cortado em reel, carrossel e post. Nada de post sem CTA de diagnóstico.', 'O conteúdo é o que faz o lead pago converter mais barato: quem chega já convencido do problema não precisa ser convencido na reunião.', 'Fabrício grava, Carol produz', 'leads orgânicos por mês', 'media'),
  (2027, 'Marketing e tráfego', 60, 2, null, false, 'Campanha de cross-sell de tráfego na base', 'Listar as empresas da carteira sem UNV Ads e ofertar tráfego com diagnóstico gratuito da conta de mídia atual.', 'Lista puxada do Nexus, dividida entre Taynon e Natállia, com script pronto. A porta de entrada é a análise gratuita da conta, não a venda direta.', 'Ads rende R$ 0,93 por real e o cliente já confia na casa. É a venda mais barata disponível e a base está quase toda sem o produto.', 'Weslley com Taynon e Natállia', 'clientes de Ads', 'alta'),
  (2027, 'Operação, entrega e CS', 10, 1, null, false, 'Ligar o vigia de risco de churn', 'Alerta automático para cliente sem reunião há 21 dias, NPS abaixo de 7, KPI em queda ou fatura vencida.', 'O alerta cai para o consultor dono e, se não for tratado em 48 horas, sobe para o Fabrício. Já existe no Nexus, falta ligar e definir o escalonamento.', 'O churn de 2026 não foi surpresa: os sinais existiam no sistema e ninguém olhava. Cliente que some 21 dias antes de cancelar é o padrão.', 'Fabrício liga, Taynon e Natállia tratam', 'clientes em alerta tratados em 48h', 'alta'),
  (2027, 'Operação, entrega e CS', 20, 2, null, false, 'Pesquisa de saída com causa raiz', 'Todo cancelamento passa por uma conversa de saída com causa raiz obrigatória, sem a opção genérica de insatisfação.', 'Roteiro de cinco perguntas aplicado pelo Fabrício, não pelo consultor que perdeu o cliente. Resultado tabulado por mês.', 'Sem causa raiz não dá para atacar o churn: a empresa fica consertando o sintoma do último cliente que saiu.', 'Fabrício', 'churn com causa identificada', 'alta'),
  (2027, 'Operação, entrega e CS', 30, 1, null, false, 'Painel de resultado em todo cliente', 'Toda empresa ativa com KPI principal definido e resultado lançado todo mês.', 'Mutirão de janeiro para cadastrar meta e KPI de quem está sem. Cliente que não quer meta é marcado como tal e sai dos alertas, em vez de poluir o painel.', 'Em outubro de 2026, 21 dos 48 clientes ativos não tinham resultado lançado no mês e 16 não tinham meta. Sem número, a renovação vira conversa de opinião.', 'Taynon e Natállia, cobrança do Fabrício', 'clientes com resultado lançado no mês', 'alta'),
  (2027, 'Operação, entrega e CS', 40, 9, 9, false, 'Zerar a carteira de entrega do fundador', 'Transferir os 6 clientes que o Fabrício atende para os consultores, inclusive o maior da casa.', 'Um cliente por mês a partir de abril, com reunião de passagem a três e 30 dias de acompanhamento. O último sai em setembro.', 'O tempo do fundador vale mais em Mastermind, evento e venda de alto valor, que são as atividades que ninguém mais faz. E dependência do dono é risco de churn quando ele falta.', 'Fabrício', 'clientes na carteira do Fabrício', 'alta'),
  (2027, 'Operação, entrega e CS', 50, 1, null, true, 'Teto de 25 clientes por pessoa', 'Nenhum consultor passa de 25 clientes. O teto é por pessoa e não é transferível entre produtos.', 'Controle na tela de carteira do consultor. Ao chegar em 22, abre a vaga de contratação; ao chegar em 25, o lead novo vai para a fila e não para a carteira.', 'Acima de 25 a entrega cai e o churn sobe: o cliente perdido custa mais do que o consultor que faltou contratar.', 'Fabrício', 'clientes por consultor', 'alta'),
  (2027, 'Financeiro', 10, 1, null, false, 'Formalizar o parcelamento do Simples', 'Fechar o parcelamento dos R$ 152.600,45 em 60 vezes.', 'Pedido feito pela contadora até 10 de janeiro. Assim que sair o valor real da parcela, trocar no plano os R$ 3.222 estimados.', 'É aproximadamente um ano de Simples não recolhido. Enquanto não for parcelado, é uma dívida que cresce e impede qualquer distribuição de lucro.', 'Fabrício com a contadora', 'parcelamento ativo e em dia', 'alta'),
  (2027, 'Financeiro', 20, 1, null, true, 'Provisão do imposto no dia do recebimento', 'Todo valor recebido tem 20,26% separado na hora para o Simples corrente.', 'Transferência automática para conta separada no fechamento semanal do contas a receber. O dinheiro não fica na conta de movimento.', 'Em 2026 a empresa recolheu R$ 178 de imposto no ano inteiro. O buraco de R$ 152 mil não veio de má-fé, veio de não separar.', 'Yasmim executa, Fabrício confere', 'provisão igual ao imposto devido do mês', 'alta'),
  (2027, 'Financeiro', 30, 1, null, false, 'Decidir a inadimplência velha', 'Resolver os R$ 17.661 vencidos há mais de 150 dias: acordo com desconto ou baixa contábil.', 'Lista caso a caso até 15 de janeiro. Acima de 180 dias, proposta de acordo com 40% de desconto; quem não aceitar, baixa.', 'Acima de 180 dias não é recebível, é prejuízo não reconhecido inflando o ativo. Carregar isso no balanço faz a empresa parecer mais saudável do que é.', 'Yasmim levanta, Fabrício decide', 'inadimplência acima de 150 dias', 'alta'),
  (2027, 'Financeiro', 40, 1, null, false, 'Abrir as duas reservas', 'Conta separada para a reserva de emergência e definição da destinação da filantropia.', 'Conta com rendimento diário e liquidez imediata, sem cartão vinculado. Aporte automático no dia 5 de cada mês: R$ 1.500 até abril, R$ 3.000 até agosto, R$ 5.000 até dezembro. Filantropia a 1% da receita.', 'Reserva que depende de sobrar nunca acontece. Vira linha fixa do mês, debitada junto com as contas.', 'Fabrício', 'saldo da reserva', 'alta'),
  (2027, 'Financeiro', 50, 4, null, true, 'Fechamento trimestral e distribuição', 'Fechar o trimestre, conferir as três travas e distribuir a participação do sócio.', 'Até o dia 10 do mês seguinte ao trimestre. Travas: lucro acima de 90% do planejado, Simples em dia e caixa acima de um mês de custo fixo após a retirada.', 'Distribuição sem regra vira retirada por necessidade, que é como a empresa chegou em 2026 sem caixa e sem imposto pago.', 'Yasmim apura, Fabrício aprova', 'trimestres com distribuição liberada', 'alta'),
  (2027, 'Financeiro', 60, 1, null, false, 'Auditar o contas a pagar e categorizar', 'Classificar todas as contas a pagar nas categorias certas e fixar a base real de custo fixo mensal.', 'Mutirão de janeiro em cima dos lançamentos sem categoria. Depois, nenhuma conta é paga sem categoria preenchida.', 'Hoje boa parte do pago está sem categoria, o que torna o DRE e a margem por produto impossíveis de ler. Sem isso o planejado contra realizado fica cego na metade das linhas.', 'Yasmim', 'lançamentos sem categoria', 'alta'),
  (2027, 'RH e pessoas', 10, 1, null, false, 'Assinar os contratos PJ novos', 'Contratos PJ de Taynon, Natállia e Weslley, no modelo sem vínculo: honorários fixos e variáveis, sem horário e sem hierarquia.', 'Dois modelos, um para consultor de gestão comercial e outro para gestor de tráfego. Assinatura pelo sistema interno do Nexus.', 'Contrato antigo com linguagem de emprego é risco trabalhista. E o modelo novo de remuneração precisa estar no papel antes de valer.', 'Fabrício', 'contratos assinados', 'alta'),
  (2027, 'RH e pessoas', 20, 4, null, false, 'Contratar o terceiro consultor', 'Consultor de gestão comercial, PJ, piso R$ 2.000 mais 7,4% de entrega e 7,4% de venda.', 'Abre quando Taynon e Natállia somarem 45 dos 50 clientes que cabem neles, e só se o gatilho de CAC e churn do primeiro trimestre bater. Perfil: experiência em PME e perfil de execução, não de teoria.', 'Contratar antes do teto é pagar vaga ociosa; depois do teto é perder cliente por entrega ruim. O gatilho resolve os dois.', 'Fabrício', 'clientes por consultor', 'alta'),
  (2027, 'RH e pessoas', 30, 7, null, false, 'Contratar o quarto consultor', 'Mesmo perfil e mesmo modelo de remuneração.', 'Condicionado ao gatilho do segundo trimestre: CAC abaixo de R$ 1.800 e churn em até 2,5 por mês.', 'A carteira de dezembro pede 93 contratos de consultoria; com teto de 25 por pessoa, são quatro consultores mais o quinto no fim do ano.', 'Fabrício', 'clientes por consultor', 'media'),
  (2027, 'RH e pessoas', 40, 10, null, false, 'Contratar o quinto consultor', 'Mesmo perfil, condicionado ao gatilho do terceiro trimestre.', 'CAC abaixo de R$ 2.000 e caixa com um mês de reserva. Se não bater, a carteira para de crescer e o lead novo entra em fila.', 'Crescer sem capacidade de entrega é como a empresa perdeu 55 clientes em 2026.', 'Fabrício', 'clientes por consultor', 'media'),
  (2027, 'RH e pessoas', 50, 8, null, false, 'Abrir a vaga do segundo gestor de tráfego', 'Começar a procurar o segundo gestor de mídia quando o Weslley chegar a 22 dos 25 clientes.', 'Projeção atual: ele fecha 2027 com 24. A vaga abre por volta de agosto para a pessoa entrar treinada em 2028.', 'A capacidade do gestor de tráfego não é transferível: consultor de consultoria não cobre fila de Ads. Descobrir isso em janeiro de 2028 é tarde.', 'Fabrício', 'clientes de Ads por gestor', 'media'),
  (2027, 'RH e pessoas', 60, 1, null, true, 'Reunião mensal de time', 'Um encontro por mês com o time inteiro: número do mês, o que travou e o que muda no mês seguinte.', 'Primeira segunda-feira do mês, com os números do painel abertos. Sem apresentação bonita: pauta é o que está vermelho.', 'Time PJ sem rotina de encontro vira prestador de serviço isolado, e aí a cultura e o padrão de entrega se perdem.', 'Fabrício', 'NPS interno', 'media'),
  (2027, 'Produto', 10, 1, null, false, 'Publicar a escada de produtos', 'A esteira completa, da Mesa gratuita ao Conselho UNV, com o critério de subida de cada degrau.', 'Um quadro só: produto, preço, para quem é, o que inclui, o que não inclui e qual o próximo degrau. Treinamento com o time comercial na semana seguinte.', 'A base compra 1,15 produto por empresa. Sem a escada desenhada, ninguém oferece o segundo produto porque não sabe qual é.', 'Fabrício', 'produtos por cliente', 'alta'),
  (2027, 'Produto', 20, 2, null, false, 'Fechar a turma do Mastermind Alpha', '20 vagas a R$ 1.500 por mês, turma fechada em fevereiro.', 'Convite direto para os 30 primeiros nomes da lista de candidatos, por ligação e não por mensagem. Encontro mensal na casa, das 14h às 20h, com dois encontros de kart no ano.', 'R$ 307 mil de receita recorrente de alta margem que não consome um minuto de consultor. É a linha que paga o aluguel da casa e torna o evento sustentável.', 'Fabrício', 'vagas ocupadas', 'alta'),
  (2027, 'Produto', 30, 1, null, false, 'CRM embutido em toda proposta nova', 'Nenhuma proposta de consultoria sai sem o CRM do Nexus incluído.', 'Muda o modelo de proposta e o discurso: o CRM não é um adicional de R$ 400, é a ferramenta onde a consultoria acontece.', 'CRM rende R$ 0,93 por real, não consome vaga de consultor e amarra o cliente na operação da UNV, o que derruba o churn. Hoje só 1 cliente usa.', 'Fabrício e os consultores', 'clientes com CRM', 'alta'),
  (2027, 'Produto', 40, 3, null, false, 'Crescer UNV Social por cross-sell', 'Levar o Social de 2 para 12 clientes ao longo do ano, sem campanha dedicada.', 'Oferta feita dentro da reunião de gestão do consultor, não por campanha separada. Antes disso, alinhar com a Carol quantos clientes o time dela entrega no padrão atual.', 'O Social rende R$ 0,50 por real, metade do Ads, mas não consome nenhuma vaga de consultor e tem churn baixo. Cresce como consequência, não como meta principal.', 'Carol, com os consultores ofertando', 'clientes de Social', 'media'),
  (2027, 'Produto', 50, 1, null, false, 'Alpha Gestão fica fora do catálogo', 'Manter o Alpha Gestão como oferta de retenção caso a caso, nunca como produto de prateleira.', 'Quando for usado, apresentar como upgrade do Mastermind, de R$ 1.500 para R$ 2.000. Nunca como consultoria com desconto.', 'Se o mercado ler o Alpha Gestão como DCT mais barato, a âncora de preço da carteira inteira cai. O desconto que salva um cliente pode custar a margem de todos.', 'Fabrício', 'nenhum', 'alta'),
  (2027, 'Eventos', 10, 1, null, true, 'Mansão Empresarial todo mês', 'Doze edições no ano, 14 vagas cada, ingresso de R$ 797.', 'Captação abre 45 dias antes de cada edição: primeiro convite para a base, depois tráfego e indicação. O erro de 2026 foi captar em cima da hora.', 'É o formato de melhor relação custo e conversão da casa: R$ 2 mil de custo, sala intimista e o fundador presente. Doze edições dão R$ 60 mil de margem e são a porta de entrada mais barata do funil.', 'Fabrício, com produção da Carol', 'inscrições pagas e clientes originados', 'alta'),
  (2027, 'Eventos', 20, 7, null, false, 'Imersão CRESCER, uma vez no ano', 'Uma edição em julho, 60 vagas, meta de lotar.', 'Captação aberta em maio. Preço e formato revistos para caber no custo de R$ 5 mil.', 'A Imersão custa duas vezes e meia a Mansão e precisa de volume só para se pagar. Faz sentido uma vez por ano como evento de marca, não como rotina.', 'Fabrício', 'vagas vendidas', 'media'),
  (2027, 'Eventos', 30, 2, null, true, 'Mesa Empreendedora trimestral', 'Quatro encontros no ano, por aplicação, gratuitos.', 'Seleção por formulário. Grupo pequeno, pauta de caso real trazido por um participante.', 'A Mesa não gera receita, gera relacionamento e qualifica quem entra na esteira. É o degrau zero do funil.', 'Fabrício', 'aplicações recebidas', 'baixa'),
  (2027, 'Eventos', 40, 1, null, false, 'Resolver a captação das 12 edições', 'Garantir 108 inscrições pagas no ano, contra as 45 de um calendário trimestral.', 'Metade das vagas tem que vir de tráfego e indicação, não só de convite para a base. Campanha permanente de Mansão no Meta, com criativo novo a cada duas edições.', 'A base atual não sustenta doze edições sozinha. Sem resolver a captação, a Mansão mensal vira sala vazia e custo fixo.', 'Weslley no tráfego, Fabrício no convite direto', 'inscrições por edição', 'alta'),
  (2027, 'Projetos e Nexus', 10, 1, null, false, 'Menu de Planejamento no ar', 'Planejado contra realizado, editável, com o plano de ação por setor e a participação do sócio.', 'Entregue em 31 de outubro de 2026. Em 2027, manter o planejado atualizado a cada revisão trimestral.', 'O plano que fica em PDF morre em fevereiro. Dentro do sistema, com o realizado chegando sozinho, ele vira rotina de gestão.', 'Fabrício', 'revisões trimestrais feitas', 'alta'),
  (2027, 'Projetos e Nexus', 20, 4, null, false, 'Painel do cliente com resultado ao vivo', 'Cada cliente enxerga o próprio resultado em tempo real, sem pedir relatório.', 'Segundo trimestre. Reaproveita o painel de KPIs que já existe, publicado por link para o cliente.', 'Cliente que vê resultado renova. E o painel tira do consultor o trabalho de montar relatório, que hoje come um dia por mês de cada um.', 'Fabrício', 'clientes com painel ativo', 'media'),
  (2027, 'Projetos e Nexus', 30, 7, null, false, 'Agentes de cobrança e retenção em produção', 'Ligar de vez os agentes de IA de cobrança e de retenção.', 'Terceiro trimestre. Cobrança nunca em grupo; retenção dispara a partir do vigia de risco.', 'São duas tarefas que ninguém gosta de fazer e por isso não são feitas. O agente não esquece e não tem vergonha de cobrar.', 'Fabrício', 'inadimplência e churn', 'media'),
  (2027, 'Projetos e Nexus', 40, 10, null, false, 'Empacotar o Nexus como produto', 'Avaliar a venda do Nexus separado da consultoria.', 'Quarto trimestre, só como estudo: precificação, custo de suporte e o que teria que mudar para servir quem não é cliente de consultoria.', 'O Nexus é o ativo mais valioso construído em 2026 e hoje só serve de ferramenta interna. Mas vender software é outro negócio, com outro custo de suporte: decidir sem estudar seria repetir o erro de abrir produto demais.', 'Fabrício', 'nenhum, é estudo', 'baixa'),
  (2027, 'Governança', 10, 3, null, true, 'Revisão trimestral do plano', 'A cada três meses: conferir os gatilhos, ajustar o planejado e decidir a distribuição.', 'Março, junho, setembro e dezembro. O planejado é editado no próprio menu de Planejamento, com o realizado ao lado.', 'Plano que não é revisto vira ficção em 90 dias. E os gatilhos de tráfego e contratação só funcionam se alguém sentar para medir.', 'Fabrício', 'revisões feitas no prazo', 'alta'),
  (2027, 'Governança', 20, 1, null, true, 'Os cinco números de segunda-feira', 'Caixa, vendas do mês, reuniões realizadas, churn e inadimplência, olhados toda segunda.', 'Painel de Controle aberto, 20 minutos, sem apresentação. O que estiver fora do padrão vira tarefa com dono e prazo na mesma reunião.', 'O problema de 2026 não foi falta de dado, foi falta de olhar. O painel existia e o churn passou de 55 sem ninguém reagir.', 'Fabrício', 'nenhum, é a rotina', 'alta');
insert into planejamento_acoes (ano, setor, ordem_setor, mes, continua, titulo, o_que, como, por_que, quem, indicador, prioridade) values
 (2027, 'Produto', 60, 5, false, 'Primeira avaliação do Mastermind',
  'Depois de três encontros, medir se a turma está entregando valor: presença, NPS e quantos subiram de degrau na esteira.',
  'Pesquisa curta com os 20 e uma conversa individual com quem faltou a dois encontros. Ajustar o formato antes do meio do ano, não depois.',
  'O Mastermind é R$ 307 mil de receita recorrente. Se a turma esvaziar no quarto mês, a linha inteira cai e não há tempo de repor no segundo semestre.',
  'Fabrício', 'presença e NPS da turma', 'alta'),

 (2027, 'Comercial', 60, 6, false, 'Revisão de meio de ano do ICP',
  'Olhar quem comprou e quem cancelou no primeiro semestre e redefinir o perfil de cliente ideal com dado, não com intuição.',
  'Cruzar os contratos novos com os cancelados por porte, segmento e origem. O que cancela mais sai do alvo da mídia.',
  'O ICP de 2026 foi desenhado por percepção. Com seis meses de dado real dá para parar de pagar por lead que nunca ia ficar.',
  'Fabrício com Weslley', 'churn por segmento', 'alta'),

 (2027, 'Operação, entrega e CS', 60, 6, false, 'Auditoria de entrega no meio do ano',
